const MAX_ATTEMPTS = 3;
const LOW_CREDITS_USD = 2;
const problems = [];

const cr = $('Check OpenRouter Credits').first()?.json ?? {};
let remaining = null;
if (cr.data && typeof cr.data.total_credits === 'number') {
  remaining = cr.data.total_credits - (cr.data.total_usage ?? 0);
  if (remaining < LOW_CREDITS_USD) problems.push(`OpenRouter credits are low: $${remaining.toFixed(2)} left.`);
} else {
  problems.push(`Could not read OpenRouter credits: ${String(cr.error?.message ?? cr.error ?? 'no data').slice(0, 200)}`);
}

const files = $('List Inbox Notes').all();
const texts = $('Extract Note Text').all();
const notes = {};
texts.forEach((item, i) => {
  const src = files[item.pairedItem?.item ?? i] ?? files[i];
  const bin = src?.binary?.data ?? {};
  const dir = (bin.directory ?? '').replace(/^\/vault-mirror\/?/, '');
  if (!dir || !bin.fileName) return;
  notes[dir + '/' + bin.fileName] = { text: item.json.noteText ?? '', fileName: bin.fileName, dir };
});
if (Object.keys(notes).length === 0) problems.push('Could not list any inbox notes in the vault mirror.');

const rows = {};
for (const r of $input.all()) if (r.json.notePath) rows[r.json.notePath] = r.json;

const dayAgo = $now.minus({ days: 1 });
let researched24h = 0;
for (const r of Object.values(rows)) {
  if (r.status === 'done' && r.updatedAt && DateTime.fromISO(r.updatedAt) > dayAgo) researched24h += 1;
}
for (const [path, n] of Object.entries(notes)) {
  const hasBacklink = n.text.includes('Researched:');
  const row = rows[path];
  if (hasBacklink) continue;
  if (row && (row.attempts ?? 0) >= MAX_ATTEMPTS && row.status !== 'done') {
    problems.push(`Gave up after ${row.attempts} attempts: ${path} (${String(row.lastError ?? '').slice(0, 120)})`);
  } else if (row && row.status === 'done') {
    problems.push(`Marked done but has no backlink: ${path}`);
  } else if (n.dir === 'Index Inbox') {
    // Watch Inbox/ is opt-in (researched only when its webhook fires), so only Index Inbox/ notes
    // are expected to be researched automatically.
    const m = n.fileName.match(/^(\d{4}-\d{2}-\d{2})/);
    if (m && DateTime.fromISO(m[1]) < $now.minus({ days: 1 })) problems.push(`Waiting for research for over a day: ${path}`);
  }
}

// 09:05 always sends a summary, so a missing morning message means the watchdog itself stopped.
// Manual (test) runs always send one too, to test the phone push.
const isDailySummary = $now.hour === 9 || $execution.mode !== 'production';
if (problems.length === 0 && !isDailySummary) return [];
const title = problems.length ? `Pebble pipeline: ${problems.length} problem${problems.length > 1 ? 's' : ''}` : 'Pebble pipeline OK';
const summary = `${researched24h} note${researched24h === 1 ? '' : 's'} researched in the last 24 hours` + (remaining === null ? '.' : `, $${remaining.toFixed(2)} OpenRouter credit left.`);
return [{ json: { title, message: (problems.length ? problems.join('\n') + '\n\n' : '') + summary, priority: problems.length ? 4 : 2, tags: problems.length ? ['warning'] : ['white_check_mark'] } }];
